TEST(golden_cw_ascii_width_classes){
    /* C1: every printable ASCII character (and DEL) has the recorded advance */
    cw_run(ASCII, NROWS(ASCII));
}

TEST(golden_cw_latin1_width_classes){
    /* C2 */
    cw_run(LATIN1, NROWS(LATIN1));
}

TEST(golden_cw_string_extents){
    /* C3 */
    HDC dc = U(GetDC)(NULL);
    REQUIRE(dc);
    for (int i = 0; i < NROWS(EXT); i++) {
        const extrow *r = &EXT[i];
        HFONT f = cw_font(r->face, r->h);
        CHECKF(f != NULL, "%s: CreateFontIndirectW failed", r->src);
        if (!f) continue;
        HGDIOBJ old = U(SelectObject)(dc, f);
        for (int j = 0; j < r->n; j++) {
            SIZE sz = {-1, -1};
            BOOL ok = U(GetTextExtentPoint32W)(dc, r->e[j].text, lstrlenW(r->e[j].text), &sz);
            CHECKF(ok && sz.cx == r->e[j].cx, "%s: extent of \"%ls\" is %ld want %d", r->src, r->e[j].text, sz.cx, r->e[j].cx);
        }
        U(SelectObject)(dc, old);
        U(DeleteObject)(f);
    }
    U(ReleaseDC)(NULL, dc);
}
